const squad = [
    {
        name: "Matheus Cunha",
        position: "Forward",
        number: 10,
        img: "data:image/jpeg;base64,"
    },
    {
        name: "Bruno Fernandes",
        position: "Midfielder",
        number: 8,
        img: "data:image/jpeg;base64,"
    },
    {
        name: "Casemiro",
        position: "Midfielder",
        number: 18,
        img: "data:image/jpeg;base64,"
    },
    {
        name: "Lisandro Martinez",
        position: "Defender",
        number: 6,
        img: "data:image/jpeg;base64,"
    },
    {
        name: "Senne Lammens",
        position: "Goalkeeper",
        number: 31,
        img: "data:image/jpeg;base64,"
    }
];

const container = document.getElementById("player-container");
const button = document.getElementById("action-button");
const resetBtn = document.getElementById("reset-button");
const heading = document.getElementById("main-heading");

function displayPlayers() {
    container.innerHTML = "";

    squad.forEach((player, index) => {
        const card = document.createElement("div");
        card.classList.add("player-card");

        card.style.animationDelay = `${index * 0.2}s`;

        card.innerHTML = `
            <img src="${player.img}" alt="${player.name}">
            <div class="player-name">${player.number} - ${player.name}</div>
            <div class="player-position">${player.position}</div>
        `;

        card.addEventListener("click", () => {
            alert(player.name);
            card.style.borderLeft = "6px solid yellow";
        });

        container.appendChild(card);
    });
}

displayPlayers();

button.addEventListener("click", () => {
    heading.textContent = "Updated Squad";
    document.body.style.backgroundColor = "#f5eded";
    heading.style.color = "#fbe122";
    document.body.style.fontFamily = "Courier New, monospace";
});

resetBtn.addEventListener("click", () => {
    heading.textContent = "Manchester United Squad";
    document.body.style.backgroundColor = "#e1d9d9";
    heading.style.color = "#fff";
    document.body.style.fontFamily = "'Segoe UI', sans-serif";
});
